// Electron main process — generated by Nativize.
// Wraps your built web app (./app) into a desktop window users double-click.
const { app, BrowserWindow, shell } = require('electron');
const path = require('path');
const serve = require('electron-serve');

// Serve the static web build through a custom protocol so SPA routing and
// absolute asset paths work (loading via file:// would break them).
const loadApp = serve({ directory: path.join(__dirname, 'app') });

function isSafeExternalUrl(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    return parsed.protocol === 'https:' || parsed.protocol === 'http:';
  } catch {
    return false;
  }
}

async function createWindow() {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      webSecurity: true,
    },
  });

  // External HTTP(S) links open in the system browser; block unsafe protocols (file:, smb:, custom URIs).
  win.webContents.setWindowOpenHandler(function (details) {
    if (isSafeExternalUrl(details.url)) {
      shell.openExternal(details.url);
    }
    return { action: 'deny' };
  });

  // Prevent untrusted top-level navigation away from the bundled app:// protocol.
  win.webContents.on('will-navigate', function (event, targetUrl) {
    if (!targetUrl.startsWith('app://')) {
      event.preventDefault();
      if (isSafeExternalUrl(targetUrl)) {
        shell.openExternal(targetUrl);
      }
    }
  });

  await loadApp(win);
}

app.whenReady().then(createWindow);
app.on('activate', function () {
  if (BrowserWindow.getAllWindows().length === 0) createWindow();
});
app.on('window-all-closed', function () {
  if (process.platform !== 'darwin') app.quit();
});
